import React, { useState } from "react";
import WeatherResults from "../WeatherResults/WeatherResults";
import "./WeatherDashboard.css"; // Import the CSS file
import { UseWeather } from "../hooks/UseWeather";
import WeatherForecast from "../WeatherForecast/WeatherForecast";
import "../styles/global.css";
import "../styles/variables.scss";
import "../styles/utility.scss";

function UserInput({ input, onSearch, onChange }) {
  return (
    <>
      <div>
        <div class="tabs" className="flex flex-row-reverse gap-lg">
        <div class="tab" onclick="openTab(event, 'Tab1')">Tab 1</div>
        <div class="tab" onclick="openTab(event, 'Tab2')">Tab 2</div>
        <div class="tab" onclick="openTab(event, 'Tab3')">Tab 3</div>  
      </div>

      </div>
      <div className="search-container">
        <input className="border-radius-xxl"
          type="text"
          value={input}
          onChange={onChange} // Use the correct prop name
          placeholder="Enter city..."
        />
        <button onClick={onSearch}>Search</button>
      </div>
    </>

  );
}

function App() {
  const [input, setInput] = useState("");
  const { results, hourlyResults, iconResponse, loading, error, fetchWeather } = UseWeather();
  const handleSearch = (e) => {
    e.preventDefault();
    fetchWeather(input); // Call fetchWeather with the input
  };


  const handleInputChange = (event) => {
    setInput(event.target.value);
  };

  return (
    <div className="weather-app">
      <UserInput input={input} onChange={handleInputChange} onSearch={handleSearch} />
      <div>
        {loading && <p>LOADING ...</p>}
        {error && <p>{error}</p>} {/* Display error directly */}
        {!results && !loading && !error && <p>There are no results</p>} {/* Only show when no results and no errors */}
      </div>
      {results && (
        <div>
          <WeatherResults results={results} hourlyResults={hourlyResults}/>
          {/* <WeatherForecast results={results} hourlyResults={hourlyResults} /> */}
        </div>

      )}
    </div>
  );
}

export default App;
